/* Natural Wonders set additions — cards appended after natural-wonders.js.
   (natural-wonders.js exceeds the push size limit, so remaining cards live here instead of being
   edited into it. Must stay directly after 'natural-wonders.js' in sets/manifest.js.) */
(function () {
  var S = window.CardSets && window.CardSets.get('natural-wonders');
  if (!S) return;
  var extra = [{"name":"Sherwood Forest","rarity":"uncommon","id":"sherwood-forest","subtitle":"Forest","details":"England's Sherwood Forest is the legendary home of Robin Hood, an ancient oak woodland whose most famous resident, the Major Oak, is centuries old.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sherwood%20Forest%2C%20May%2C%202017-5.jpg?width=1024"},{"name":"Pantanal","rarity":"uncommon","id":"pantanal","subtitle":"Wetland","details":"Brazil's Pantanal is the world's largest tropical wetland, a seasonally flooded plain where jaguars, capybaras and giant otters thrive in the shallows.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pantanal%2C%20south-central%20South%20America%205170.jpg?width=1024"},{"name":"Serengeti Savanna","rarity":"uncommon","id":"serengeti-savanna","subtitle":"Savanna","details":"Tanzania's Serengeti savanna is an endless sea of grass dotted with acacia trees, famous for the great annual migration of wildebeest and zebra.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Serengeti-Landscape-2012.JPG?width=1024"},{"name":"Okavango Delta","rarity":"uncommon","id":"okavango-delta","subtitle":"Wetland","details":"Botswana's Okavango Delta is a vast inland wetland where a river fans into floodplains, creating islands of palms that draw elephants and hippos.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Okavango%20Delta%2C%20Botswana1.jpg?width=1024"},{"name":"Kakamega Forest","rarity":"uncommon","id":"kakamega-forest","subtitle":"Forest","details":"Kenya's Kakamega Forest is a last fragment of the great Guineo-Congolian rainforest that once stretched across Africa, rich in primates and birds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kakamega%20forest%20view.jpg?width=1024"},{"name":"Spiny Forest","rarity":"uncommon","id":"spiny-forest","subtitle":"Forest","details":"Madagascar's spiny forest is a surreal landscape of bottle baobabs and thorny ocotillo-like trees, where most plants grow nowhere else on Earth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Spiny%20Forest%20Ifaty%20Madagascar.jpg?width=1024"},{"name":"Avenue of the Baobabs","rarity":"uncommon","id":"avenue-of-the-baobabs","subtitle":"Grove","details":"Madagascar's Avenue of the Baobabs lines a dirt road with majestic Grandidier's baobabs, ancient bottle trees that tower over the surrounding scrub.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/All%C3%A9e%20des%20baobabs%20Morondava%20Madagascar.jpg?width=1024"},{"name":"Crooked Forest","rarity":"uncommon","id":"crooked-forest","subtitle":"Forest","details":"Poland's Crooked Forest is a grove of pine trees that all bend sharply at the base into the same strange hook shape, and nobody knows exactly why.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Krzywy%20las%20-%20002.jpg?width=1024"},{"name":"Mongolian Steppe","rarity":"uncommon","id":"mongolian-steppe","subtitle":"Steppe","details":"The Mongolian steppe is one of the world's largest grasslands, a rolling ocean of grass under huge skies, grazed for centuries by nomadic herders.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A%20Field%20Is%20Pictured%20Outside%20Ulaanbaatar%20After%20Secretary%20Kerry%20Attended%20a%20%22Mini-Nadaam%22%20%2827266112900%29.jpg?width=1024"},{"name":"Brazilian Cerrado","rarity":"uncommon","id":"brazilian-cerrado","subtitle":"Savanna","details":"Brazil's Cerrado is the world's most biodiverse savanna, a mosaic of grassland and twisted trees that shelters giant anteaters, maned wolves and rheas.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Morro%20cabeludo%20-%20Parque%20dos%20Pireneus%20-%20Piren%C3%B3polis%20-%20Goi%C3%A1s%2001.jpg?width=1024"},{"name":"Los Llanos","rarity":"uncommon","id":"los-llanos","subtitle":"Grassland","details":"Los Llanos is a vast tropical grassland plain shared by Venezuela and Colombia, flooding in the rains and teeming with capybaras, anacondas and birds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Llanos3.jpg?width=1024"},{"name":"The Pampas","rarity":"uncommon","id":"the-pampas","subtitle":"Grassland","details":"The Pampas are South America's fertile lowland grasslands, a vast plain of rich soil long used for cattle ranching and grain, home of the gaucho.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SerraGeralI.jpg?width=1024"},{"name":"Arctic Tundra","rarity":"uncommon","id":"arctic-tundra","subtitle":"Tundra","details":"The Arctic tundra is a treeless land of low shrubs, mosses and wildflowers above permafrost, lit all summer by the midnight sun near the pole.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Arctic%20Tundra%20%288540635536%29.jpg?width=1024"},{"name":"New Forest","rarity":"uncommon","id":"new-forest","subtitle":"Forest","details":"England's New Forest was set aside as a royal hunting ground in 1079, and its ancient woods and heaths are still grazed by free-roaming ponies.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Beech%20trees%20in%20Mallard%20Wood%2C%20New%20Forest%20-%20geograph.org.uk%20-%20779513.jpg?width=1024"},{"name":"Forest of Dean","rarity":"uncommon","id":"forest-of-dean","subtitle":"Forest","details":"The Forest of Dean is one of England's surviving royal forests, an ancient oak and beech woodland tucked between the Wye and Severn rivers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Clearing%20in%20Puzzlewood%20-%20geograph.org.uk%20-%208342729.jpg?width=1024"},{"name":"Breiðamerkurjökull Ice Cave","rarity":"uncommon","id":"breidamerkurjokull-ice-cave","subtitle":"Ice Cave","details":"Inside Iceland's largest glacier, meltwater carves glowing blue caves each winter, their crystal ice shifting and reforming with every passing season.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ice%20cave%20at%20Brei%C3%B0amerkurj%C3%B6kull%20glacier%2C%20Iceland%2C%2020240719%201549%202724.jpg?width=1024"},{"name":"A-23a Iceberg","rarity":"uncommon","id":"a-23a-iceberg","subtitle":"Iceberg","details":"Calved from Antarctica in 1986, this colossal iceberg spent decades grounded before drifting north, for years the largest floating iceberg on Earth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Iceberg%20A23A%20Approaching%20South%20Georgia%20Island%20%28MODIS%202025-02-21%29.jpg?width=1024"},{"name":"Fly Geyser","rarity":"uncommon","id":"fly-geyser","subtitle":"Geyser","details":"Nevada's accidental geyser grew from a failed well into rainbow mineral cones, still spouting hot water across the desert on private ranch land today.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fly%20geyser.jpg?width=1024"},{"name":"Pamukkale","rarity":"uncommon","id":"pamukkale","subtitle":"Hot Spring","details":"In Turkey, warm mineral water has built dazzling white travertine terraces over thousands of years, spilling from pool to bright pool down the hillside.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pamukkale%2002.jpg?width=1024"},{"name":"Danakil Depression","rarity":"uncommon","id":"danakil-depression","subtitle":"Phenomenon","details":"Ethiopia's surreal sulphur springs boil in acid greens and yellows in one of the hottest inhabited places on Earth, far below sea level in the desert.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dallol%2C%20Danakil%20Depression.jpg?width=1024"},{"name":"Darvaza Gas Crater","rarity":"uncommon","id":"darvaza-gas-crater","subtitle":"Crater","details":"Turkmenistan's fiery crater has burned natural gas in the Karakum Desert for decades, a glowing pit of flame visible for miles across the night sands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Darvaza%20Gas%20Crater.jpg?width=1024"},{"name":"Lambert Glacier","rarity":"uncommon","id":"lambert-glacier","subtitle":"Glacier","details":"The largest glacier on Earth outside the polar ice sheets, Antarctica's Lambert Glacier drains a vast share of the East Antarctic Ice Sheet to the sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Icefall%2C%20Lambert%20Glacier%2C%20Antarctica%20%284404056289%29.jpg?width=1024"},{"name":"Franz Josef Glacier","rarity":"uncommon","id":"franz-josef-glacier","subtitle":"Glacier","details":"This New Zealand glacier descends from the Southern Alps almost to sea level, flowing through temperate rainforest in a rare meeting of ice and green.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Franz%20Josef%20glacier%202012.jpg?width=1024"},{"name":"Athabasca Glacier","rarity":"uncommon","id":"athabasca-glacier","subtitle":"Glacier","details":"Canada's most visited glacier spills from the Columbia Icefield in Alberta, its meltwater feeding rivers that reach three different oceans far away.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Athabasca%20Glacier%20BenWBell.jpg?width=1024"},{"name":"Hubbard Glacier","rarity":"uncommon","id":"hubbard-glacier","subtitle":"Glacier","details":"Alaska's longest tidewater glacier stretches seventy-six miles, its seven-mile-wide face calving thunderously into Disenchantment Bay near Yakutat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hubbard%20Glacier%20Alaska.jpg?width=1024"},{"name":"Champagne Pool","rarity":"uncommon","id":"champagne-pool","subtitle":"Hot Spring","details":"New Zealand's most colourful hot spring steams orange and green at Wai-O-Tapu, its bright rim coloured by minerals and heat-loving microorganisms.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/ChampagnePool-Wai-O-Tapu%20rotated%20MC.jpg?width=1024"},{"name":"Bora Bora","rarity":"uncommon","id":"bora-bora","subtitle":"Island","details":"A worn volcanic peak, Mount Otemanu, rises from one of the Pacific's most famous lagoons, ringed by a coral reef and a necklace of low sandy motu islets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Boraboraluft.jpg?width=1024"},{"name":"Seychelles","rarity":"uncommon","id":"seychelles","subtitle":"Archipelago","details":"Ancient granite boulders frame the beaches of this Indian Ocean archipelago, the world's only oceanic islands formed from continental granite rock.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Grand_Anse-La_Digue-Seychellen.jpg?width=1024"},{"name":"Fernando de Noronha","rarity":"uncommon","id":"fernando-de-noronha","subtitle":"Archipelago","details":"A protected volcanic archipelago off Brazil of emerald bays and twin sea stacks, a breeding refuge for spinner dolphins, seabirds and green sea turtles.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/111_Baia_dos_Porcos_04.jpg?width=1024"},{"name":"Zanzibar","rarity":"uncommon","id":"zanzibar","subtitle":"Archipelago","details":"Unguja, the main island of the Zanzibar Archipelago off Tanzania, is fringed by white coral-sand beaches and reefs once famed for spices and trade winds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Zanzibar_Beach.JPG?width=1024"},{"name":"Phi Phi Islands","rarity":"uncommon","id":"phi-phi-islands","subtitle":"Island","details":"Sheer limestone cliffs enclose Maya Bay on uninhabited Phi Phi Leh in Thailand, a lagoon-like cove of white sand and clear water in the Andaman Sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Playa_Maya%2C_Ko_Phi_Phi%2C_Tailandia%2C_2013-08-19%2C_DD_05.JPG?width=1024"},{"name":"Azores","rarity":"uncommon","id":"azores","subtitle":"Archipelago","details":"Nine volcanic islands mid-Atlantic, where the twin blue and green crater lakes of Sete Cidades fill a vast caldera on the island of Sao Miguel.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/View_overlooking_the_Sete_Cidades_Lagoon%2C_S%C3%A3o_Miguel_island%2C_Azores_%28Portugal%29.jpg?width=1024"},{"name":"Lofoten Islands","rarity":"uncommon","id":"lofoten-islands","subtitle":"Archipelago","details":"Jagged granite peaks rise straight from Arctic Norwegian fjords in the Lofoten Islands, long famed for cod fisheries, red cabins and northern lights.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Reine_at_Reinefjorden%2C_2010_September.jpg?width=1024"},{"name":"Aleutian Islands","rarity":"uncommon","id":"aleutian-islands","subtitle":"Archipelago","details":"A 1,900-kilometre arc of volcanic islands reaches from Alaska toward Russia, separating the Bering Sea from the Pacific amid fog, surf and active volcanoes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Alaska_Maritime_National_Wildlife_Refuge%3B_Chagulak_Island_in_the_Aleutian_Islands.jpg?width=1024"},{"name":"Whitsunday Islands","rarity":"uncommon","id":"whitsunday-islands","subtitle":"Archipelago","details":"Swirling white silica sand and turquoise water meet at Hill Inlet on the largest of the Whitsundays, a chain of 74 drowned mountain islands off Queensland.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Whitehaven_Beach%2C_Whitsunday_Island%2C_Queensland.jpg?width=1024"},{"name":"Isle of Skye","rarity":"uncommon","id":"isle-of-skye","subtitle":"Island","details":"The Quiraing landslip on Skye's Trotternish ridge is a shifting landscape of pinnacles and plateaus above the sea, on Scotland's most dramatic island.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Quiraing%2C_Isle_of_Skye%2C_Scotland_-_Diliff.jpg?width=1024"},{"name":"Aitutaki","rarity":"uncommon","id":"aitutaki","subtitle":"Lagoon","details":"A triangular coral atoll in the Cook Islands encloses a vast turquoise lagoon scattered with 15 small islets, ringed by reef and deep Pacific blue.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Maina_Island%2C_Aitutaki_Lagoon%2C_Cook_Islands.jpg?width=1024"},{"name":"Mount Baker","rarity":"common","id":"mount-baker","subtitle":"Volcano","details":"This heavily glaciated Washington volcano rises 3,286 metres near the Canadian border, holding the world record for snowfall measured in a single season.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mount_Baker_from_Boulder_Creek.jpg?width=1024"},{"name":"Mount Adams","rarity":"common","id":"mount-adams","subtitle":"Volcano","details":"Washington's second-highest peak is a broad volcano rising 3,743 metres, built by overlapping cones and ringed by glaciers, lava fields and huckleberry meadows.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mount_Adams_Morrison_Creek_ski_tour_%286_May_2025%29.jpg?width=1024"},{"name":"Grand Teton","rarity":"common","id":"grand-teton","subtitle":"Peak","details":"This Wyoming peak rises 4,199 metres almost directly from the Jackson Hole valley floor, a sheer granite spire with no foothills to soften its dramatic rise.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Grand_Teton_from_Hurricane_Pass_2026.jpg?width=800"},{"name":"Longs Peak","rarity":"common","id":"longs-peak","subtitle":"Peak","details":"This Colorado fourteener rises 4,346 metres in Rocky Mountain National Park, famed for its flat summit, sheer Diamond face and exposed Keyhole climbing route.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fall05-LongsPeakCU_JPG_RSZ_md.jpg?width=1024"},{"name":"Pikes Peak","rarity":"common","id":"pikes-peak","subtitle":"Peak","details":"This Colorado peak rises 4,302 metres above Colorado Springs, its broad summit reached by road and cog railway and famed for far views over the Great Plains.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Beautiful_Image_of_Pikes_Peak_%28IMG_0136%29.jpg?width=1024"},{"name":"Mount Washington","rarity":"common","id":"mount-washington","subtitle":"Mountain","details":"New Hampshire's highest peak rises 1,917 metres in the White Mountains, notorious for extreme winds and rapidly changing weather above its rocky summit cone.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/White_Mountains_12_30_09_81.jpg?width=1024"},{"name":"Mount Mitchell","rarity":"common","id":"mount-mitchell","subtitle":"Mountain","details":"The highest peak east of the Mississippi rises 2,037 metres in North Carolina, its summit cloaked in spruce-fir forest above the Black Mountain range.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mount_Mitchell_from_Mt._Mitchell_overlook_NC.jpg?width=1024"},{"name":"Katahdin","rarity":"common","id":"katahdin","subtitle":"Mountain","details":"Maine's highest mountain rises 1,606 metres in Baxter State Park, a granite massif whose Knife Edge ridge marks the northern end of the Appalachian Trail.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Katahdin.jpg?width=1024"},{"name":"Haleakala","rarity":"common","id":"haleakala","subtitle":"Volcano","details":"This Hawaiian shield volcano rises 3,055 metres on Maui, its summit depression filled with colourful cinder cones and rare silversword plants in volcanic soil.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Haleakala_crater_%281%29.jpg?width=1024"},{"name":"Mount Batur","rarity":"common","id":"mount-batur","subtitle":"Volcano","details":"This active Balinese volcano rises 1,717 metres inside a double caldera beside Lake Batur, its dark lava fields and summit rim popular for sunrise climbs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/View_Of_Mt.Batur_on_April_8th_2026.jpg?width=1024"},{"name":"Mount Pinatubo","rarity":"common","id":"mount-pinatubo","subtitle":"Volcano","details":"This Philippine volcano's huge 1991 eruption formed a summit caldera now filled by a turquoise lake, after ejecting ash that circled the entire globe.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mt_Pinatubo_trekking_-_panoramio_%285%29.jpg?width=1024"},{"name":"Mount Mayon","rarity":"common","id":"mount-mayon","subtitle":"Volcano","details":"This Philippine volcano rises 2,463 metres in Albay, celebrated for its almost perfectly symmetric cone and frequent eruptions of lava, ash and glowing debris.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mount_Mayon_Cagsawa_field_view_close-up_%28Busay%2C_Daraga%2C_Albay%3B_04-21-2023%29.jpg?width=1024"},{"name":"Mount Apo","rarity":"common","id":"mount-apo","subtitle":"Volcano","details":"The Philippines' highest peak rises 2,954 metres on Mindanao, a dormant volcano with boulder fields, mossy forests, lakes and a three-peaked summit ridge.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tuktok_ng_Pilipinas.jpg?width=1024"},{"name":"Mount Hallasan","rarity":"common","id":"mount-hallasan","subtitle":"Volcano","details":"South Korea's highest peak is a shield volcano rising 1,947 metres on Jeju Island, topped by a crater lake and slopes covered in distinctive volcanic rock.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hallasan_Above.jpg?width=1024"},{"name":"Mount Paektu","rarity":"common","id":"mount-paektu","subtitle":"Volcano","details":"This volcano on the China-Korea border rises 2,744 metres, its summit caldera holding deep blue Heaven Lake inside one of the largest crater lakes on Earth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Paektu%20Mountain%27s%20Heaven%20Lake.jpg?width=1024"},{"name":"Mount Kosciuszko","rarity":"common","id":"mount-kosciuszko","subtitle":"Mountain","details":"Australia's highest mainland peak rises 2,228 metres in the Snowy Mountains, a gentle rounded summit reached across alpine herbfields and glacial lakes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kosciuszko_main_range_from_Scammel_Spur_Lookout_%28cropped%29.jpg?width=1024"},{"name":"Mount Ruapehu","rarity":"common","id":"mount-ruapehu","subtitle":"Volcano","details":"New Zealand's largest active volcano rises 2,797 metres on the North Island, holding a warm crater lake and the country's two largest commercial ski areas.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mount_Ruapehu_October_9%2C_2023_%28cropped%29.jpg?width=1024"},{"name":"Mount Taranaki","rarity":"common","id":"mount-taranaki","subtitle":"Volcano","details":"This near-perfect volcanic cone rises 2,518 metres in New Zealand, standing alone above farmland with a secondary cone, Fanthams Peak, low on its flank.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mt_Taranaki.JPG?width=1024"},{"name":"Mount Ngauruhoe","rarity":"common","id":"mount-ngauruhoe","subtitle":"Volcano","details":"This steep New Zealand volcano rises 2,291 metres as a perfect cone on the Tongariro massif, built entirely by eruptions within roughly the last millennia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Le_Ngauruhoe_et_le_Ruapehu_vus_du_sommet_du_Tongariro.jpg?width=1024"},{"name":"Scafell Pike","rarity":"common","id":"scafell-pike","subtitle":"Mountain","details":"England's highest mountain rises 978 metres in the Lake District, a rugged rocky summit above deep valleys, tarns and the dramatic Wasdale screes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Scafell_massif.jpg?width=1024"},{"name":"Zugspitze","rarity":"common","id":"zugspitze","subtitle":"Mountain","details":"Germany's highest peak rises 2,962 metres on the Austrian border, a limestone massif with small glaciers, steep faces and wide views over four countries.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Zugspitze_2.JPG?width=1024"},{"name":"Grossglockner","rarity":"common","id":"grossglockner","subtitle":"Mountain","details":"Austria's highest mountain rises 3,798 metres in the Hohe Tauern, a sharp pyramid above the long Pasterze glacier, the largest glacier left in the country.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gro%C3%9Fglockner_from_behind_the_glass_panorama_tower.JPG?width=1024"},{"name":"Mount Parnassus","rarity":"common","id":"mount-parnassus","subtitle":"Mountain","details":"This Greek mountain rises 2,457 metres above Delphi, its twin peaks long sacred to Apollo and the Muses, with limestone slopes above the Gulf of Corinth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Parnassos2.jpg?width=1024"},{"name":"Musala","rarity":"common","id":"musala","subtitle":"Peak","details":"The Balkans' highest peak rises 2,925 metres in Bulgaria's Rila Mountains, a rocky summit named, by tradition, for a phrase meaning near God in old Turkish.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Musala_IMG_1447.jpg?width=1024"},{"name":"Lower Falls","rarity":"common","id":"lower-falls","subtitle":"Waterfall","details":"The Yellowstone River drops 94 metres, nearly twice Niagara's height, into the yellow-walled Grand Canyon of the Yellowstone in a thundering plunge.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Grand%20canyon%20of%20Yellowstone%20and%20Yellowstone%20fall%20nn%20edit1.jpg?width=1024"},{"name":"Bridalveil Fall","rarity":"common","id":"bridalveil-fall","subtitle":"Waterfall","details":"Bridalveil Creek drops 188 metres over a granite cliff, and in spring wind often blows the falling water sideways in a fine, veil-like sheet of spray.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bridelveil_Falls_Yosemite.jpg?width=1024"},{"name":"Vernal Fall","rarity":"common","id":"vernal-fall","subtitle":"Waterfall","details":"The Merced River pours 97 metres over a granite ledge beside the Mist Trail, soaking the stairway beside it with spray during the spring snowmelt peak.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vernal_Fall%2C_Yosemite_NP%2C_CA%2C_US_-_Diliff.jpg?width=800"},{"name":"Cumberland Falls","rarity":"common","id":"cumberland-falls","subtitle":"Waterfall","details":"The Cumberland River drops about 21 metres over a sandstone ledge 38 metres wide, and on clear full-moon nights its mist can form a rare moonbow.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cumberland_falls_2015_1.jpg?width=1024"},{"name":"Amicalola Falls","rarity":"common","id":"amicalola-falls","subtitle":"Waterfall","details":"A series of cascades drops about 222 metres down a mountainside, making this the tallest cascading waterfall in Georgia and a landmark of its foothills.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Amicalola_Falls.JPG?width=1024"},{"name":"Erawan Falls","rarity":"common","id":"erawan-falls","subtitle":"Cascade","details":"Seven tiers of falls spill over limestone into emerald pools, each level named in local tradition, with travertine terraces shaping the milky water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Erawan_Waterfall%2C_Kanchanaburi_Province%2C_Thailand_-_June_2004.jpg?width=1024"},{"name":"Kuang Si Falls","rarity":"common","id":"kuang-si-falls","subtitle":"Cascade","details":"Spring water rich in minerals tumbles over travertine tiers into turquoise pools, building pale limestone shelves as it descends through the jungle.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kuang%20Si%20Falls%20and%20a%20turquoise%20water%20pool%20in%20Luang%20Prabang%20province%20Laos.jpg?width=1024"},{"name":"Wentworth Falls","rarity":"common","id":"wentworth-falls","subtitle":"Waterfall","details":"Jamison Creek spills over sandstone cliffs in the Blue Mountains in several tiers totalling about 187 metres, above a deep, eucalypt-forested valley.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Upper%20Wentworth%20Falls%2C%20NSW%2C%20Australia%20-%20Nov%202008.jpg?width=1024"},{"name":"Fitzroy Falls","rarity":"common","id":"fitzroy-falls","subtitle":"Waterfall","details":"Yarrunga Creek plunges about 81 metres over a sandstone escarpment into a forested valley, its flow swelling dramatically after heavy highland rain.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/FitzroyFalls.jpg?width=1024"},{"name":"Ruby Falls","rarity":"common","id":"ruby-falls","subtitle":"Waterfall","details":"An underground stream drops about 44 metres inside a limestone cavern beneath a mountain, illuminated in changing colours deep below the surface rock.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ruby%20Falls%20underground.jpg?width=1024"},{"name":"Anna Ruby Falls","rarity":"common","id":"anna-ruby-falls","subtitle":"Waterfall","details":"Two creeks drop side by side, one about 47 metres and the other about 15 metres, joining below in a double fall reached by a short paved forest trail.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lower_Falss.jpg?width=1024"},{"name":"Bash Bish Falls","rarity":"common","id":"bash-bish-falls","subtitle":"Waterfall","details":"Bash Bish Brook splits around a boulder and drops about 24 metres in twin streams into a clear pool in a gorge on a forested state-line mountainside.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bash_Bish_Falls.jpg?width=800"},{"name":"Salt Creek Falls","rarity":"common","id":"salt-creek-falls","subtitle":"Waterfall","details":"Salt Creek plunges about 87 metres over a columnar basalt cliff formed by ancient lava flows, into a canyon cut through an old-growth mountain forest.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Salt_Creek_Falls_1.jpg?width=1024"},{"name":"Proxy Falls","rarity":"common","id":"proxy-falls","subtitle":"Waterfall","details":"Two veiled cascades drop about 69 metres over moss-covered lava, seeming to vanish at the base where the water sinks into porous volcanic rock below.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Proxy_Falls.JPG?width=1024"},{"name":"Tahquamenon Falls","rarity":"common","id":"tahquamenon-falls","subtitle":"Waterfall","details":"The Tahquamenon River drops about 15 metres over a ledge nearly 61 metres wide, its amber colour coming from tannins leached from cedar swamps upstream.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Upper_Tahquamenon_Falls_Fall_2007.jpeg?width=1024"},{"name":"Great Falls","rarity":"common","id":"great-falls","subtitle":"Cascade","details":"The Potomac River drops about 23 metres through a series of jagged rocky cascades and channels, squeezed between steep cliffs in a narrow gorge.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Great_Falls_Potomac_River_VA.JPG?width=1024"},{"name":"Minnehaha Falls","rarity":"common","id":"minnehaha-falls","subtitle":"Waterfall","details":"Minnehaha Creek drops about 16 metres over a limestone ledge behind which a path passes, in a city park glen long celebrated in American poetry.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Minnehaha_Falls%2C_Minneapolis.jpg?width=1024"},{"name":"South Falls","rarity":"common","id":"south-falls","subtitle":"Waterfall","details":"The South Fork of Silver Creek drops about 54 metres over a basalt cliff, and a trail carved into the rock passes directly behind its falling curtain.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/South_Falls%2C_Silver_Falls_State_Park.jpg?width=1024"},{"name":"Tallulah Gorge","rarity":"common","id":"tallulah-gorge","subtitle":"Gorge","details":"Tallulah Gorge in Georgia cuts nearly 1,000 feet deep for two miles through quartzite ridges, with the Tallulah River rushing over a series of cascades below.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tallulah%20Gorge%20view%20from%20an%20overlook%2C%20May%202017%201.jpg?width=1024"},{"name":"Rio Grande Gorge","rarity":"common","id":"rio-grande-gorge","subtitle":"Gorge","details":"New Mexico's Rio Grande cut a dramatic 800-foot chasm through volcanic basalt plains near Taos, now protected as part of a national monument.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rio%20Grande%20Gorge%2C%20New%20Mexico%2C%20USA2.jpg?width=1024"},{"name":"Letchworth Gorge","rarity":"common","id":"letchworth-gorge","subtitle":"Gorge","details":"New York's Genesee River plunges over three great waterfalls through the deep, forested Letchworth Gorge, often called the Grand Canyon of the East.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Letchworth%20State%20Park%20-%2020150809%20-%2023%20-%20Genesee%20Gorge%20near%20Lower%20Falls.jpg?width=1024"},{"name":"Flaming Gorge","rarity":"common","id":"flaming-gorge","subtitle":"Gorge","details":"Named for its brilliant red canyon walls, Flaming Gorge straddles Utah and Wyoming where the Green River carved through the Uinta Mountains.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Flaming%20Gorge-Uintas%20National%20Scenic%20Byway%20-%20Boating%20in%20Red%20Canyon%20on%20Flaming%20Gorge%20-%20NARA%20-%207718362.jpg?width=1024"},{"name":"Itaimbezinho Canyon","rarity":"common","id":"itaimbezinho-canyon","subtitle":"Canyon","details":"Brazil's Itaimbezinho is a sheer-walled canyon nearly 2,400 feet deep, its araucaria forest rim giving way to waterfalls that vanish into the depths.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/C%C3%A2nion%20Itaimbezinho%20-%20Canyon%20Itaimbezinho%20-%20panoramio%20%281%29.jpg?width=1024"},{"name":"Cotahuasi Canyon","rarity":"common","id":"cotahuasi-canyon","subtitle":"Canyon","details":"Peru's remote Cotahuasi is among the deepest canyons in the Americas, plunging over 11,000 feet from rim to river in the southern Andes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cotahuasi%20Canyon.jpg?width=1024"},{"name":"Bicaz Gorge","rarity":"common","id":"bicaz-gorge","subtitle":"Gorge","details":"Romania's Bicaz Gorge slices through the Carpathians in a narrow pass of towering limestone walls, following the winding Bicaz River and its rapids.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheile%20Bicazului%2C%20%28gorges%20de%20bicaz%29%20%282%29.jpg?width=1024"},{"name":"Iron Gates Gorge","rarity":"common","id":"iron-gates-gorge","subtitle":"Gorge","details":"The Danube squeezes through the Iron Gates, a dramatic 83-mile gorge between Romania and Serbia where cliffs rise far above Europe's great river.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Djerdap%20%28Iron%20Gate%29%20gorge.JPG?width=1024"},{"name":"Dades Gorge","rarity":"common","id":"dades-gorge","subtitle":"Gorge","details":"Morocco's Dades Gorge winds between rust-red cliffs and kasbahs, its famous hairpin road climbing a valley carved by the Dades River in the Atlas foothills.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20dades%20gorge%2C%20southern%20Morocco.jpg?width=1024"},{"name":"Hancock Gorge","rarity":"common","id":"hancock-gorge","subtitle":"Gorge","details":"Western Australia's Hancock Gorge descends by ladders and wades into a narrow chasm of banded iron rock over two billion years old in Karijini.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hancock%20Gorge%20karijini.jpg?width=1024"},{"name":"Sonoran Desert","rarity":"common","id":"sonoran-desert","subtitle":"Desert","details":"The lushest desert in North America spreads across Arizona and Mexico, defined by giant saguaro cacti and two distinct rainy seasons each year.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Carnegiea%20Sonoran%20Desert%2007.jpg?width=1024"},{"name":"Chihuahuan Desert","rarity":"common","id":"chihuahuan-desert","subtitle":"Desert","details":"North America's largest desert stretches from New Mexico and Texas deep into Mexico, a high land of creosote, agave, gypsum dunes and limestone ranges.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chihuahuan%20Desert%2001.jpg?width=1024"},{"name":"Great Victoria Desert","rarity":"common","id":"great-victoria-desert","subtitle":"Desert","details":"Australia's largest desert is a vast, sparsely peopled land of red sand dunes, spinifex grasslands and salt lakes across two states.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Shattuck%2068127%2C%20Anne%20Beadell%20Highway%2C%20west%20of%20Neale%20Junction%2C%20Western%20Australia%20%2851255218785%29.jpg?width=1024"},{"name":"Simpson Desert","rarity":"common","id":"simpson-desert","subtitle":"Desert","details":"Australia's Simpson Desert holds the world's longest parallel sand dunes, red ridges running for hundreds of miles across the continent's arid heart.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SimpsonDesert.jpg?width=1024"},{"name":"Tabernas Desert","rarity":"common","id":"tabernas-desert","subtitle":"Desert","details":"Europe's only true desert lies in Spain's Almeria province, a parched landscape of ravines and badlands made famous as a classic film location.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20Tabernas%20desert%20%2810859889356%29.jpg?width=1024"},{"name":"Bardenas Reales","rarity":"common","id":"bardenas-reales","subtitle":"Badlands","details":"Spain's Bardenas Reales is a stark semi-desert of clay badlands, ravines and lone pinnacles like Castildetierra, sculpted by wind and rare heavy rain.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castildetierra%20-%20Summer%20morning.jpg?width=1024"},{"name":"Providence Canyon","rarity":"common","id":"providence-canyon","subtitle":"Canyon","details":"Providence Canyon in Georgia drops some 150 feet through gullies cut into soft coastal-plain sediments, exposing bands of white, pink, orange and red clay.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Providence%20Canyon%20from%20rim.jpg?width=1024"},{"name":"Mesquite Flat Dunes","rarity":"common","id":"mesquite-flat-dunes","subtitle":"Dunes","details":"Death Valley's Mesquite Flat Dunes ripple near Stovepipe Wells, their sinuous crests constantly reshaped by wind and glowing at dawn and dusk.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mesquite%20Flat%20Sand%20Dunes%20Panorama%20Morning%202013.jpg?width=1024"},{"name":"Kelso Dunes","rarity":"common","id":"kelso-dunes","subtitle":"Dunes","details":"California's Kelso Dunes rise 650 feet in the Mojave Preserve and are famous for booming sounds made when dry sand avalanches down their steep faces.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kelso%20Dunes%20in%20the%20Mojave%20Preserve%20%2849531609003%29.jpg?width=1024"},{"name":"Snake River Canyon","rarity":"common","id":"snake-river-canyon","subtitle":"Canyon","details":"Idaho's Snake River Canyon cuts nearly 500 feet through basalt near Twin Falls, spanned by the Perrine Bridge high above the green river.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Snake%20River%20Canyon%20Idaho%202007%20%28cut%29.jpg?width=1024"},{"name":"Lake Geneva","rarity":"common","id":"lake-geneva","subtitle":"Lake","details":"Shared by Switzerland and France, crescent-shaped Lake Geneva is western Europe's largest Alpine lake, with Montreux and Geneva on its shores.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Geneva%20from%20Chillon%20Castle.jpg?width=1024"},{"name":"Lake Garda","rarity":"common","id":"lake-garda","subtitle":"Lake","details":"Italy's largest lake stretches between the Alps and the Po Plain, with olive groves, lemon gardens and medieval villages along its mild shores.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SIR%20-%20Lake%20Garda%20and%20Sirmione%20peninsula%20seen%20from%20Scaligero%20Castle%2C%20Italy%2C%202014.jpg?width=1024"},{"name":"Lake Wanaka","rarity":"common","id":"lake-wanaka","subtitle":"Lake","details":"A long glacial lake in New Zealand's Otago region, Wanaka is framed by the Southern Alps and known for the lone willow tree standing in its shallows.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/ThatWanakaTree%20at%20Sunrise.jpg?width=1024"},{"name":"Great Salt Lake","rarity":"common","id":"great-salt-lake","subtitle":"Lake","details":"Utah's Great Salt Lake is the largest saltwater lake in the Western Hemisphere; its salinity varies, and brine shrimp thrive in its salty waters.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Great%20Salt%20Lake%20UT1.jpg?width=1024"},{"name":"Lake Tanganyika","rarity":"common","id":"lake-tanganyika","subtitle":"Lake","details":"The world's longest freshwater lake and second deepest, Tanganyika is home to hundreds of fish species found nowhere else on Earth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Tanganyika%20sun%20set.jpg?width=1024"},{"name":"Lake Malawi","rarity":"common","id":"lake-malawi","subtitle":"Lake","details":"This African Great Lake is famed for its extraordinary diversity of cichlid fish, with more fish species than any other lake in the world.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Canoes%20on%20Lake%20Malawi.jpg?width=1024"},{"name":"Lake Nakuru","rarity":"common","id":"lake-nakuru","subtitle":"Lake","details":"A shallow alkaline lake in Kenya's Rift Valley, Nakuru is famed for the flocks of lesser flamingos that at times turn its shoreline pink.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Large%20number%20of%20flamingos%20at%20Lake%20Nakuru.jpg?width=1024"},{"name":"Indus River","rarity":"common","id":"indus-river","subtitle":"River","details":"One of Asia's great rivers, the Indus flows about 3,180 kilometres from Tibet through Pakistan, sustaining one of history's oldest civilisations.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Indus%20River%2C%20Ladakh%2C%20India.jpg?width=1024"},{"name":"Colorado River","rarity":"common","id":"colorado-river","subtitle":"River","details":"Carving the Grand Canyon over millions of years, the Colorado flows about 2,330 kilometres from the Rocky Mountains to the Gulf of California.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Colorado%20River%20edit.jpg?width=1024"},{"name":"Saint Lawrence River","rarity":"common","id":"saint-lawrence-river","subtitle":"River","details":"Linking the Great Lakes to the Atlantic Ocean, the Saint Lawrence flows about 1,197 kilometres past Montreal and Quebec City in eastern Canada.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Saint%20Lawrence%20River%20in%20Rimouski%202.jpg?width=1024"},{"name":"Parana River","rarity":"common","id":"parana-river","subtitle":"River","details":"South America's second-longest river runs about 4,880 kilometres through Brazil, Paraguay and Argentina before joining the Rio de la Plata estuary.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Confluence%20of%20the%20Iguazu%20and%20Parana%20rivers%2C%20Puerto%20Iguazu%2C%20Misiones%2C%20Argentina%2C%206th.%20Jan.%202011%20-%20Flickr%20-%20PhillipC.jpg?width=1024"},{"name":"Cinque Terre","rarity":"common","id":"cinque-terre","subtitle":"Coast","details":"Five colourful fishing villages cling to terraced cliffs on Italy's Ligurian coast, linked by cliff paths above the clear Mediterranean Sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Manarola%20is%20one%20of%20the%20famous%20villages%20of%20the%20scenic%20%27Cinque%20Terre%27%20coast%20in%20eastern%20Liguria.jpg?width=1024"},{"name":"Algarve Coast","rarity":"common","id":"algarve-coast","subtitle":"Coast","details":"Southern Portugal's Algarve coast is a procession of golden limestone cliffs, natural sea arches, hidden coves and grottoes carved by the Atlantic.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Portimao-Benagil%20coast%20%2830%29.jpg?width=1024"},{"name":"Skeleton Coast","rarity":"common","id":"skeleton-coast","subtitle":"Coast","details":"Namibia's remote Skeleton Coast is where the Namib Desert meets Atlantic surf, a foggy shore named for whale bones and many shipwrecks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Shipwreck%20in%20Skeleton%20Coast%20%2817301891002%29.jpg?width=1024"},{"name":"Lake Ohrid","rarity":"common","id":"lake-ohrid","subtitle":"Lake","details":"One of Europe's oldest and deepest lakes, Ohrid between North Macedonia and Albania shelters hundreds of species found nowhere else on Earth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Ohrid%20in%20Albania%20%28by%20Pudelek%29.JPG?width=1024"},{"name":"Lake Toba","rarity":"common","id":"lake-toba","subtitle":"Lake","details":"Sumatra's Lake Toba fills the caldera of a supervolcano that erupted about 74,000 years ago, one of the largest volcanic eruptions of its era.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lake%20Toba%20from%20Simalem%2C%20North%20Sumatra.jpg?width=1024"},{"name":"Lake Inle","rarity":"common","id":"lake-inle","subtitle":"Lake","details":"In Myanmar's Shan Hills, shallow Inle Lake is known for stilt-house villages, floating gardens and fishermen who row with one leg wrapped on an oar.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20160805%20-%20Inle%20Lake%2C%20Myanmar%20-%208453%20DxO.jpg?width=1024"},{"name":"Lake Argentino","rarity":"common","id":"lake-argentino","subtitle":"Lake","details":"Patagonia's largest lake, Argentino is fed by glaciers including Perito Moreno, whose towering ice front calves icebergs into its milky waters.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lago%20Argentino%2C%20camino%20al%20Glaciar%20Perito%20Moreno%20%28a%C3%B1o%202009%29%2C%20Santa%20Cruz.jpg?width=1024"},{"name":"Loch Lomond","rarity":"common","id":"loch-lomond","subtitle":"Lake","details":"Scotland's largest loch by surface area straddles the Highland boundary, dotted with more than thirty islands and backed by the peak of Ben Lomond.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20loch%20lomond.JPG?width=1024"},{"name":"Douro River","rarity":"common","id":"douro-river","subtitle":"River","details":"The Douro winds from Spain through northern Portugal to Porto, its steep valley terraced with the vineyards that produce port wine.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Douro%20River%20Valley%20sunrise.jpg?width=1024"},{"name":"Etretat Cliffs","rarity":"common","id":"etretat-cliffs","subtitle":"Cliff","details":"Normandy's Etretat cliffs are white chalk walls carved by the sea into natural arches and a famous needle rock rising from the English Channel.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cliffs%20of%20Etretat%2C%20Normandy%2C%20France%2C%20December%202022.jpg?width=1024"},{"name":"Thurston Lava Tube","rarity":"common","id":"thurston-lava-tube","subtitle":"Lava Tube","details":"Hawaii's Thurston Lava Tube, or Nahuku, formed about 500 years ago when a river of lava drained away, leaving a smooth tunnel through lush rainforest.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Thurston_Lava_Tube%2C_Big_Island.jpg?width=1024"},{"name":"Manjanggul Cave","rarity":"common","id":"manjanggul-cave","subtitle":"Lava Tube","details":"Jeju Island's Manjanggul Cave is one of the world's finest lava tubes, 7.4 kilometres long with a huge lava column rising 7.6 metres from its floor.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Manjanggul_caves_36.jpg?width=1024"},{"name":"Ape Cave","rarity":"common","id":"ape-cave","subtitle":"Lava Tube","details":"Washington's Ape Cave is a 4.2-kilometre lava tube on Mount St. Helens, one of the longest in North America, staying near 6 degrees all year round.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ape_Cave_at_Mount_St._Helens_National_Volcanic_Monument_in_Washington_1.jpg?width=1024"},{"name":"Cenote Suytun","rarity":"common","id":"cenote-suytun","subtitle":"Cenote","details":"Mexico's Cenote Suytun is famed for a single shaft of sunlight that falls through a hole in its roof onto a round stone platform in turquoise water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cenote_Suytun_2009_06.jpg?width=1024"},{"name":"Dos Ojos","rarity":"common","id":"dos-ojos","subtitle":"Cenote","details":"Mexico's Dos Ojos, or Two Eyes, links two clear cenotes in one flooded cave system near Tulum, a favourite route for divers exploring in sunlight.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20230324_-_Cenote_Dos_Ojos_-_5.jpg?width=1024"},{"name":"Actun Tunichil Muknal","rarity":"common","id":"actun-tunichil-muknal","subtitle":"Cave","details":"Belize's Actun Tunichil Muknal, the Cave of the Crystal Sepulchre, preserves ancient Maya pottery and a calcite-encrusted skeleton deep in its chambers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Actun_Tunichil_Muknal.jpg?width=1024"},{"name":"Harrison's Cave","rarity":"common","id":"harrisons-cave","subtitle":"Cave","details":"Barbados' Harrison's Cave carries visitors by tram past stalactites, stalagmites, waterfalls and pools through a crystallised limestone cavern system.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Harrisons_Cave_%286989193817%29.jpg?width=1024"},{"name":"Caves of Drach","rarity":"common","id":"caves-of-drach","subtitle":"Cave","details":"Mallorca's Caves of Drach hide Lake Martel, one of the largest underground lakes in the world, where concerts are played from boats on the still water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Interior_de_las_Cuevas_del_Drach.jpg?width=1024"},{"name":"Nerja Cave","rarity":"common","id":"nerja-cave","subtitle":"Cave","details":"Spain's Nerja Cave holds vast galleries near the Mediterranean coast, including one of the world's largest stalagmites, rising 32 metres from the floor.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cueva_de_Nerja_2020.jpg?width=1024"},{"name":"Frasassi Caves","rarity":"common","id":"frasassi-caves","subtitle":"Cave","details":"Italy's Frasassi Caves open into immense chambers of white stalactites, including the Abisso Ancona, large enough to hold Milan Cathedral inside it.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Frasassi_caves.jpg?width=1024"},{"name":"Akiyoshido Cave","rarity":"common","id":"akiyoshido-cave","subtitle":"Cave","details":"Japan's Akiyoshido Cave stretches about 10 kilometres beneath Akiyoshidai, with terraced rimstone pools and a clear river running through its halls.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Akiyoshid%C5%8D_interior_Aug_24_1059am.jpg?width=1024"},{"name":"Blue Lake Cave","rarity":"common","id":"blue-lake-cave","subtitle":"Cave","details":"Brazil's Blue Lake Cave, Gruta do Lago Azul, holds a pool of startlingly blue water lit by sunlight, with bones of giant Ice Age animals on its floor.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gruta_do_Lago_Azul_-Tiziana_Paulina_Sepulveda_Henao_%2804%29.jpg?width=1024"},{"name":"Cacahuamilpa Caves","rarity":"common","id":"cacahuamilpa-caves","subtitle":"Cave","details":"Mexico's Cacahuamilpa Caves form one of the country's largest cave systems, with huge illuminated chambers up to 21 metres high near Taxco, Guerrero.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/08Cacahuamilpa.JPG?width=1024"},{"name":"Kungur Ice Cave","rarity":"common","id":"kungur-ice-cave","subtitle":"Cave","details":"Russia's Kungur Ice Cave in the Urals preserves glittering ice crystals, frozen grottoes and about 70 underground lakes beneath a gypsum mountain.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kungur_Ice_Cave_P6242165_2575.jpg?width=1024"},{"name":"Undara Lava Tube","rarity":"common","id":"undara-lava-tube","subtitle":"Lava Tube","details":"Australia's Undara Lava Tube in Queensland is part of one of the longest lava flows from a single volcano, its wide arched tunnels now home to bats.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Undara_Lava_Tubes.JPG?width=1024"},{"name":"Fontainebleau Forest","rarity":"common","id":"fontainebleau-forest","subtitle":"Forest","details":"France's Forest of Fontainebleau is famed for its sandstone boulder fields amid oak and pine woods, a beloved landscape of painters and climbers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fontainebleau%20apremont.JPG?width=1024"},{"name":"Bavarian Forest","rarity":"common","id":"bavarian-forest","subtitle":"Forest","details":"The Bavarian Forest, on Germany's Czech border, is Central Europe's largest forest wilderness, left to grow wild with spruce, fir and roaming lynx.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bayerischer%20wald%20intakt.jpg?width=1024"},{"name":"Caledonian Forest","rarity":"common","id":"caledonian-forest","subtitle":"Forest","details":"Scotland's Caledonian Forest is the remnant of a vast ancient pinewood, where gnarled Scots pines shelter red squirrels, capercaillie and wildcats.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ancient%20Caledonian%20Forest%2C%20Glen%20Tanar%20-%20geograph.org.uk%20-%206992.jpg?width=1024"},{"name":"Atlantic Forest","rarity":"common","id":"atlantic-forest","subtitle":"Forest","details":"Brazil's Atlantic Forest once ran along the whole coast, a lush rainforest rich in endemic species, from golden lion tamarins to towering jequitiba trees.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mata%20atlantica%20-%20Parque%20do%20Zizo%20S%C3%A3o%20Paulo.jpg?width=1024"},{"name":"Bwindi Impenetrable Forest","rarity":"common","id":"bwindi-impenetrable-forest","subtitle":"Forest","details":"Uganda's Bwindi Impenetrable Forest is a dense, mountainous jungle of tangled vines and trees, famous as a sanctuary for mountain gorillas.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bwindi%20Impenetrable%20National%20Park%20desde%20el%20Broadbill%20Forest%20Camp%2020190925%20085152.jpg?width=1024"},{"name":"Muir Woods","rarity":"common","id":"muir-woods","subtitle":"Forest","details":"California's Muir Woods preserves a cathedral-like grove of old-growth coast redwoods just north of San Francisco, saved from logging in 1908.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Muir%20Woods%20National%20Monument%20%2847879029461%29.jpg?width=1024"},{"name":"Zhangjiajie Forest","rarity":"common","id":"zhangjiajie-forest","subtitle":"Forest","details":"China's Zhangjiajie forest is a misty world of thousands of towering sandstone pillars clothed in pine and vines, like a forest of floating mountains.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/1%20tianzishan%20wulingyuan%20zhangjiajie%202012.jpg?width=1024"},{"name":"Red Forest","rarity":"common","id":"red-forest","subtitle":"Forest","details":"Ukraine's Red Forest grew near Chernobyl, where pines turned rust-red after the 1986 disaster; wildlife now thrives in its quiet, empty woods.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Red%20Forest%20trees.jpg?width=1024"},{"name":"The Dark Hedges","rarity":"common","id":"the-dark-hedges","subtitle":"Grove","details":"Northern Ireland's Dark Hedges is an avenue of beech trees planted in the 18th century, their twisted branches weaving a tunnel over the road.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Dark%20Hedges%20in%20August%202024.jpg?width=1024"},{"name":"Araucaria Forest","rarity":"common","id":"araucaria-forest","subtitle":"Forest","details":"The araucaria forests of Chile and Argentina are ruled by monkey puzzle trees, ancient conifers with spiky, umbrella crowns unchanged for ages.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Araucaria%20araucana%2C%20Conguill%C3%ADo%20National%20Park%2C%20Chile.jpg?width=1024"},{"name":"Miombo Woodlands","rarity":"common","id":"miombo-woodlands","subtitle":"Woodland","details":"Miombo woodlands cover a huge swath of southern Africa, open forests of brachystegia trees that flush copper-red with new leaves each spring.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Flickr%20-%20ggallice%20-%20Miombo%20woodland%20%281%29.jpg?width=1024"},{"name":"Smoky Mountains Forest","rarity":"common","id":"smoky-mountains-forest","subtitle":"Forest","details":"The Great Smoky Mountains hold one of America's most diverse forests, where blue haze from the trees gives the ancient Appalachian ridges their name.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Great%20Smoky%20Mountains%20National%20Park1.jpg?width=1024"},{"name":"Teutoburg Forest","rarity":"common","id":"teutoburg-forest","subtitle":"Forest","details":"Germany's Teutoburg Forest is a long ridge of beech-covered hills, famed as the site where Germanic tribes ambushed Roman legions in 9 AD.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blick-%C3%BCber-den-Teutoburger-Wald1.jpg?width=1024"},{"name":"Epping Forest","rarity":"common","id":"epping-forest","subtitle":"Forest","details":"Epping Forest is London's largest open space, an ancient woodland of beech, oak and hornbeam pollards stretching out from the city's northeast edge.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fairmead%20Road%20High%20Beach%20Epping%20Forest%20Essex%20England%2001.jpg?width=800"},{"name":"Sonian Forest","rarity":"common","id":"sonian-forest","subtitle":"Forest","details":"Belgium's Sonian Forest, on Brussels' edge, is a soaring cathedral of beech trees, one of Europe's finest surviving ancient beech forests.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Autumn%20light%20in%20the%20Sonian%20Forest.jpg?width=800"},{"name":"Kampinos Forest","rarity":"common","id":"kampinos-forest","subtitle":"Forest","details":"Poland's Kampinos Forest, beside Warsaw, mixes pine woods with inland sand dunes and marshes, a wild refuge where moose were reintroduced.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kampinos%20Forest%20-%20panoramio.jpg?width=1024"},{"name":"Hainich Forest","rarity":"common","id":"hainich-forest","subtitle":"Forest","details":"Germany's Hainich is one of Europe's largest unbroken deciduous forests, an old beech wilderness crossed by a famous treetop canopy walkway.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sch%C3%B6nstedt%2C%20Nationalpark%20Hainich%2C%20Ausblick%20vom%20Baumkronenpfad%20--%202017%20--%200197.jpg?width=1024"},{"name":"Nyungwe Forest","rarity":"common","id":"nyungwe-forest","subtitle":"Forest","details":"Rwanda's Nyungwe is one of Africa's oldest montane rainforests, a misty highland jungle home to chimpanzees and hundreds of orchid species.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nyungwe%20Canopy%20Walk.jpg?width=1024"},{"name":"Socotra Dragon Tree Grove","rarity":"common","id":"socotra-dragon-tree-grove","subtitle":"Grove","details":"On Yemen's Socotra island, groves of dragon blood trees raise umbrella-shaped crowns, bleeding red resin when their bark is cut or wounded.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dragon%20blood%20trees%20in%20Socotra%20Island%2C%20Yemen.jpg?width=1024"},{"name":"Avenue of the Giants","rarity":"common","id":"avenue-of-the-giants","subtitle":"Grove","details":"California's Avenue of the Giants is a famous road winding through towering old-growth redwood groves in Humboldt Redwoods State Park.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Avenue%20of%20the%20Giants%20-%20California%20-%207402231924.jpg?width=1024"},{"name":"Vatnajokull","rarity":"common","id":"vatnajokull","subtitle":"Glacier","details":"Vatnajokull in Iceland is Europe's largest ice cap by volume, covering about eight percent of the country and hiding several active volcanoes beneath its ice.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Island%20Vatnaj%C3%B6kull%2002.JPG?width=1024"},{"name":"Big Four Ice Caves","rarity":"common","id":"big-four-ice-caves","subtitle":"Ice Cave","details":"Washington's famous snow caves form each summer as meltwater and warm air hollow the base of Big Four Mountain, beautiful but dangerously fragile.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Big%20Four%20Ice%20Cave.jpg?width=1024"},{"name":"Steamboat Geyser","rarity":"common","id":"steamboat-geyser","subtitle":"Geyser","details":"The tallest active geyser on Earth, in Yellowstone, can blast water higher than a thirty-storey building during its rare and unpredictable eruptions.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Steamboat%20Geyser%20in%20Yellowstone.jpg?width=1024"},{"name":"Great Geysir","rarity":"common","id":"great-geysir","subtitle":"Geyser","details":"Iceland's original erupting spring gave all geysers their name, though it now sleeps for long stretches between rare, earthquake-wakened eruptions.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Great%20Geysir%20in%20Iceland%206.JPG?width=1024"},{"name":"El Tatio","rarity":"common","id":"el-tatio","subtitle":"Geyser","details":"High in Chile's Atacama Desert, one of the world's largest geyser fields steams in the thin dawn air at more than four thousand metres above the sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/G%C3%A9iseres%20del%20Tatio%2C%20Atacama%2C%20Chile%2C%202016-02-01%2C%20DD%2003-05%20HDR.JPG?width=1024"},{"name":"Blue Lagoon","rarity":"common","id":"blue-lagoon","subtitle":"Hot Spring","details":"Iceland's milky blue geothermal lagoon formed in a lava field, its warm mineral-rich water held back by black volcanic rock beside a power plant.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blue%20Lagoon%20Geothermal%20pool%2003.jpg?width=1024"},{"name":"Mer de Glace","rarity":"common","id":"mer-de-glace","subtitle":"Glacier","details":"France's largest glacier, a sea of ice above Chamonix, winds seven kilometres down Mont Blanc, scarred with deep crevasses and grey moraine ridges.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mer%20de%20Glace%20Glacier%20in%20France%20-%202009-08-06.jpg?width=1024"},{"name":"Tasman Glacier","rarity":"common","id":"tasman-glacier","subtitle":"Glacier","details":"New Zealand's longest glacier carves its way from Mount Cook, calving icebergs into a grey lake that has grown as the ice has retreated uphill fast.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tasman%20Lake%20and%20Tasman%20Glacier.jpg?width=1024"},{"name":"Fox Glacier","rarity":"common","id":"fox-glacier","subtitle":"Glacier","details":"This fast-moving West Coast glacier slides downhill through New Zealand rainforest, creaking and cracking as it travels up to four metres in a day.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fox%20Glacier%20in%20Westland%20National%20Park%2006.jpg?width=1024"},{"name":"Matanuska Glacier","rarity":"common","id":"matanuska-glacier","subtitle":"Glacier","details":"Alaska's great valley glacier stretches twenty-seven miles from the Chugach Mountains, a walkable river of blue ice, rubble and deep moulins today.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Matanuska%20Glacier%20mouth.jpg?width=1024"},{"name":"Columbia Glacier","rarity":"common","id":"columbia-glacier","subtitle":"Glacier","details":"Once Alaska's fastest-retreating glacier, this tidewater giant in Prince William Sound calves icebergs into a fjord watched closely by scientists.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Columbia%20Glacier%2C%20Alaska%2C%20USA%20-%20April%209th%2C%202022%20%2851997657226%29.jpg?width=1024"},{"name":"Rhone Glacier","rarity":"common","id":"rhone-glacier","subtitle":"Glacier","details":"Source of the Rhone River, this Swiss glacier spills from a high Alpine pass, its grotto carved anew into the blue ice for visitors each summer time.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rhonegletscher%20from%20Belvedere.JPG?width=1024"},{"name":"Morteratsch Glacier","rarity":"common","id":"morteratsch-glacier","subtitle":"Glacier","details":"Switzerland's Morteratsch Glacier trails beneath the Bernina peaks, its meltwater stream and moraines marking how far the ice once reached below.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Morteratsch%20glacier%201.jpg?width=1024"},{"name":"Grinnell Glacier","rarity":"common","id":"grinnell-glacier","subtitle":"Glacier","details":"Montana's showpiece glacier perches above a turquoise lake in Glacier National Park, shrinking fast but still creased with bright blue crevasses.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Grinnell%20Glacier%20with%20Lake%20and%20Salamander%20Glacier.jpg?width=1024"},{"name":"Exit Glacier","rarity":"common","id":"exit-glacier","subtitle":"Glacier","details":"The only roadside glacier in Kenai Fjords, Alaska's Exit Glacier spills from the Harding Icefield, its trailside markers showing years of retreat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Exit%20Glacier%2C%20Alaska.jpg?width=1024"},{"name":"Morning Glory Pool","rarity":"common","id":"morning-glory-pool","subtitle":"Hot Spring","details":"Yellowstone's rainbow hot spring shifts colour with its water temperature, its blue centre fading to green and gold as the pool has cooled over time.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Morning%20Glory%20Pool%20Yellowstone%20National%20Park.jpg?width=1024"},{"name":"Lord Howe Island","rarity":"common","id":"lord-howe-island","subtitle":"Island","details":"Two towering volcanic peaks guard a crescent lagoon on this Tasman Sea island, home to the world's southernmost coral reef and many endemic species.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mount_Lidgebird_and_Mount_Gower.JPG?width=1024"},{"name":"Aldabra","rarity":"common","id":"aldabra","subtitle":"Atoll","details":"One of the world's largest raised coral atolls, Aldabra shelters over 100,000 giant tortoises and a lagoon that empties and fills dramatically each tide.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Picard_Island_Beach_%2833192890326%29.jpg?width=1024"},{"name":"Santorini","rarity":"common","id":"santorini","subtitle":"Island","details":"A drowned volcanic caldera forms this crescent Greek island, its sheer cliffs of layered ash and lava rising 300 metres from deep blue Aegean water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The_Santorini_Caldera.jpg?width=1024"},{"name":"Kangaroo Island","rarity":"common","id":"kangaroo-island","subtitle":"Island","details":"Wind and sea have sculpted the Remarkable Rocks, huge lichen-stained granite boulders perched above the surf on Australia's third-largest island.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Remarkable_Rocks_01.jpg?width=1024"},{"name":"South Georgia","rarity":"common","id":"south-georgia","subtitle":"Island","details":"Glacier-carved peaks and penguin-crowded beaches line this subantarctic island, a wildlife refuge for king penguins, elephant seals and albatrosses.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/View_over_the_king_penguin_colony_in_Gold_Harbour%2C_South_Georgia.jpg?width=1024"},{"name":"Svalbard","rarity":"common","id":"svalbard","subtitle":"Archipelago","details":"Halfway between Norway and the North Pole, this high Arctic archipelago of glaciers and fjords is home to polar bears, walruses and the midnight sun.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama_Svalbard_Isfjorden.jpg?width=1024"},{"name":"Rangiroa","rarity":"common","id":"rangiroa","subtitle":"Atoll","details":"One of the world's largest atolls, Rangiroa is a ring of 240 tiny islets around a lagoon so wide that its far shore often sits below the horizon.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rangiroa-W.jpg?width=1024"},{"name":"Midway Atoll","rarity":"common","id":"midway-atoll","subtitle":"Atoll","details":"A ring of coral and three low islands in the remote North Pacific, Midway hosts the world's largest colony of Laysan albatrosses each breeding season.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Midway_Atoll_aerial_photo_2008.JPG?width=1024"},{"name":"Surtsey","rarity":"common","id":"surtsey","subtitle":"Island","details":"Surtsey erupted from the sea off Iceland in 1963, creating one of Earth's youngest islands, kept as a pristine laboratory for how life colonises new land.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Surtsey_by_Brian_Gratwicke.jpg?width=1024"},{"name":"Deception Island","rarity":"common","id":"deception-island","subtitle":"Island","details":"A flooded volcanic caldera in Antarctica forms this horseshoe island, where ships sail through Neptune's Bellows into a natural harbour at Whalers Bay.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2_Whalers_Bay_-_Deception_Island.jpg?width=1024"},{"name":"Ball's Pyramid","rarity":"common","id":"balls-pyramid","subtitle":"Sea Stack","details":"The world's tallest volcanic sea stack rises 562 metres from the Tasman Sea, a sheer remnant of an ancient shield volcano southeast of Lord Howe Island.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Balls_Pyramid_near_Lord_Howe_Island.jpg?width=1024"},{"name":"Twelve Apostles","rarity":"common","id":"twelve-apostles","subtitle":"Sea Stack","details":"Towering limestone stacks stand offshore along Australia's Great Ocean Road, carved from the cliffs by Southern Ocean waves and still slowly eroding.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Princetown_%28AU%29%2C_Port_Campbell_National_Park%2C_Twelve_Apostles_--_2019_--_0930.jpg?width=1024"},{"name":"Kiritimati","rarity":"common","id":"kiritimati","subtitle":"Atoll","details":"The world's largest coral atoll by land area, Kiritimati in Kiribati wraps a huge network of hypersaline lagoons famed for bonefish and seabird colonies.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kiritimati-EO.jpg?width=1024"},{"name":"Palmyra Atoll","rarity":"common","id":"palmyra-atoll","subtitle":"Atoll","details":"A lush, uninhabited atoll of rainforest islets and bright lagoons south of Hawaii, protected as one of the Pacific's most intact coral reef ecosystems.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ansicht_des_Palmyra_Atoll_National_Wildlife_Refuge%2C_Vereinigte_Staaten.jpg?width=1024"},{"name":"Capri","rarity":"common","id":"capri","subtitle":"Island","details":"Three famous sea stacks, the Faraglioni, rise from the Tyrrhenian Sea off Capri, a limestone island of cliffs, grottoes and clear water south of Naples.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Faraglioni_Capri_2.jpg?width=1024"},{"name":"Tasmania","rarity":"common","id":"tasmania","subtitle":"Island","details":"Wineglass Bay curves in a perfect arc of white sand beneath pink granite peaks on Tasmania, Australia's large mountainous island state in the Bass Strait.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Beach%2C_Wineglass_Bay%2C_Freycinet_National_Park%2C_Tasmania.jpg?width=800"}];
  extra.forEach(function (x) {
    if (S.byId.has(x.id)) return;
    var c = { id: x.id, num: S.cards.length + 1, name: x.name, rarity: x.rarity,
              subtitle: x.subtitle, details: x.details, image: x.image, logo: '' };
    S.cards.push(c);
    S.byId.set(c.id, c);
    if (S.pools[c.rarity]) S.pools[c.rarity].push(c);
  });
})();
